from bisect import bisect_left


def smallestCommon(grid):
    for v in grid[0]:
        found = True
        for row in grid[1:]:
            i = bisect_left(row, v)
            if i == len(row):
                return -1
            if row[i] != v:
                found = False
                break
        if found:
            return v
    return -1
